/**
 * Per-channel sun-transmittance tints the scattering shell can't provide: its
 * premultiplied alpha is a luminance scalar, so it dims but never colours,
 * and never touches light striking a surface.
 *
 * - Surface patch: direct light × sun→fragment transmittance (sunset light).
 *   Inside a deep column (under Venus's deck, under Titan's haze) the direct
 *   beam is gone, and the patch lights the ground with the column's diffuse
 *   sky instead.
 * - {@link VIEW_TINT_GLSL}: camera→fragment chroma for the sun disc,
 *   per-fragment since from orbit the disc outsizes the atmosphere band.
 * - {@link sunPathTransmittance}: CPU ratio for corona/star point.
 *
 * Tints are T/lum(T) ratios, so the shell's alpha keeps sole ownership of
 * dimming. Same squashed space as the shell (oblate ellipsoid = unit sphere):
 * on gas giants the polar dip is hundreds of scale heights, so a spherical
 * march would read mid-latitudes as deep underground. Radii passed in are the
 * solid body's; the shell's deck offset is added here, like in the shell.
 */

import {
	DataTexture,
	type Material,
	type MeshStandardMaterial,
	type Texture,
	Vector3
} from 'three';
import {
	type AtmosphereNode,
	type AtmosphereParams,
	deepColumnTexture,
	referenceRadiusKm,
	TERRAIN_DIP_KM
} from './atmosphere';
import { type EclipseSelfUniforms, getEclipseSceneUniforms } from './eclipse-shadow';
import { chainShaderHook } from '$lib/scene/shaders/program-cache-key';

/** Kept under the shell's LIGHT_STEPS — the surface patch runs over full-screen landed terrain. */
const FRAGMENT_STEPS = 6;
const CPU_STEPS = 16;

/** Scene-wide enable flag (mirrors the atmosphere visibility setting); shared
 *  value ref like the eclipse uniforms, mutated in place each frame. */
const SCENE = { uAtmoTEnable: { value: 1 } };

export function setSunTransmittanceEnabled(on: boolean): void {
	SCENE.uAtmoTEnable.value = on ? 1 : 0;
}

const PARAM_DECLS = `
	uniform vec3 uAtmoTBetaR;        // Rayleigh β, per planet radius, (R,G,B)
	uniform vec3 uAtmoTBetaMExt;     // Mie extinction β, per planet radius
	uniform vec3 uAtmoTBetaA;        // absorber band β, per planet radius
	uniform float uAtmoTRayleighH;
	uniform float uAtmoTMieH;
	uniform float uAtmoTAbsCenter;
	uniform float uAtmoTAbsWidth;
	uniform float uAtmoTTopR;        // shell radius / planet radius
	uniform float uAtmoTBlockR;      // sun-ray block sphere, ~terrain dip below datum
	uniform float uAtmoTBakedComp;
	uniform float uAtmoTRadiusScene;
	uniform float uAtmoTEnable;
	uniform vec3 uAtmoTCenter;       // body centre, scene/world space
	uniform vec3 uAtmoTSpinAxis;     // unit, world — body pole
	uniform float uAtmoTStretch;     // equatorial radius / polar radius, >= 1
	uniform float uAtmoTMeshR;       // host mesh's nominal radius / planet radius
	// The deep-column profile (rows: downward flux over its surface value,
	// up/down ratio, extinction per km) from the solid surface at
	// uAtmoTDeepBaseR up uAtmoTDeepSpanR. uAtmoTDeepBlend: the camera's own
	// weight inside the column, 0 above its blend band.
	uniform sampler2D uAtmoTDeepTex;
	uniform float uAtmoTDeepN;
	uniform float uAtmoTDeepBaseR;
	uniform float uAtmoTDeepSpanR;   // 0 = none
	uniform float uAtmoTDeepKmPerRadius;
	uniform float uAtmoTDeepIrradiance; // render-unit irradiance luminance, sun overhead
	uniform float uAtmoTDeepBlend;

	vec3 atmoTDeepTap(float row, float u) {
		float w = clamp(u, 0.0, 1.0) * (uAtmoTDeepN - 1.0);
		float i0 = min(floor(w), uAtmoTDeepN - 2.0);
		float v = (row + 0.5) / 3.0;
		vec3 a = texture2D(uAtmoTDeepTex, vec2((i0 + 0.5) / uAtmoTDeepN, v)).rgb;
		vec3 b = texture2D(uAtmoTDeepTex, vec2((i0 + 1.5) / uAtmoTDeepN, v)).rgb;
		return mix(a, b, w - i0);
	}

	// Whether the host mesh sits inside the deep column — the solid surface
	// does, a cloud overlay at a deck does not.
	bool atmoTUnderDeck() {
		return uAtmoTDeepSpanR > 0.0 && uAtmoTMeshR < uAtmoTDeepBaseR + 0.5 * uAtmoTDeepSpanR;
	}

	// Shell parity: stretch the spin-axis component so the oblate ellipsoid
	// becomes the unit sphere. Linear, so rays stay straight; squashed path
	// lengths are converted back to world lengths by the callers.
	vec3 atmoTSquash(vec3 v) {
		return v + (uAtmoTStretch - 1.0) * dot(v, uAtmoTSpinAxis) * uAtmoTSpinAxis;
	}
`;

const SUN_TINT_GLSL = `
	// Eclipse's uSunDir/uEclipseSelfPos are declared after this chunk's
	// insertion point — same value refs re-bound under own names.
	uniform vec3 uAtmoTSunDir;
	${PARAM_DECLS}

	// Column (∫density above h) of the linear-tent absorber, in radii of
	// surface-density-equivalent path — mirrors tentColumnAboveKm.
	float atmoTTentColumn(float h) {
		if (uAtmoTAbsWidth <= 0.0) return 0.0;
		float lo = uAtmoTAbsCenter - uAtmoTAbsWidth;
		float hi = uAtmoTAbsCenter + uAtmoTAbsWidth;
		if (h <= lo) return uAtmoTAbsWidth;
		if (h >= hi) return 0.0;
		if (h <= uAtmoTAbsCenter)
			return uAtmoTAbsWidth - (h - lo) * (h - lo) / (2.0 * uAtmoTAbsWidth);
		return (hi - h) * (hi - h) / (2.0 * uAtmoTAbsWidth);
	}

	vec3 atmoSunTint(vec3 worldPos) {
		if (uAtmoTEnable < 0.5) return vec3(1.0);
		vec3 p = atmoTSquash((worldPos - uAtmoTCenter) / uAtmoTRadiusScene);
		// Snap the start to the mesh's analytic sphere: interpolated positions
		// ripple below it between vertices (chords, DEM), and the exponential
		// density turns that tessellation ripple into per-quad tint blotches.
		p = normalize(p) * uAtmoTMeshR;
		// Inside the column the beam crosses what is left of it above: gone on
		// the ground, whole at its top. Gated on the host mesh, not the
		// fragment: an overlay at the top itself ripples under it between
		// vertices.
		if (atmoTUnderDeck()) {
			float zf = (length(p) - uAtmoTDeepBaseR) / uAtmoTDeepSpanR;
			if (zf < 1.0) {
				float mu = max(dot(normalize(p), uAtmoTSunDir), 0.05);
				float dz = (1.0 - zf) / 6.0;
				vec3 tau = vec3(0.0);
				for (int i = 0; i < 6; i++) tau += atmoTDeepTap(2.0, zf + dz * (float(i) + 0.5));
				return exp(-tau * (dz * uAtmoTDeepSpanR * uAtmoTDeepKmPerRadius / mu));
			}
		}
		vec3 sd = atmoTSquash(uAtmoTSunDir);
		float sunLen = length(sd);
		sd /= sunLen;
		float b = dot(p, sd);
		float c = dot(p, p);
		// Sun under the horizon: zero, not huge τ — only clips DEM slopes, the
		// analytic sphere's NdotL is already ≤ 0 there.
		float d = b * b - (c - uAtmoTBlockR * uAtmoTBlockR);
		if (d > 0.0 && -b - sqrt(d) > 0.0) return vec3(0.0);
		d = b * b - (c - uAtmoTTopR * uAtmoTTopR);
		if (d <= 0.0) return vec3(1.0);
		float tFar = -b + sqrt(d);
		if (tFar <= 0.0) return vec3(1.0);
		// Fragment sits inside the shell → the segment starts at the fragment.
		float dt = tFar / ${FRAGMENT_STEPS.toFixed(1)};
		vec3 od = vec3(0.0);
		for (int i = 0; i < ${FRAGMENT_STEPS}; i++) {
			float h = max(length(p + sd * (dt * (float(i) + 0.5))) - 1.0, 0.0);
			od += vec3(
				exp(-h / uAtmoTRayleighH),
				exp(-h / uAtmoTMieH),
				max(0.0, 1.0 - abs(h - uAtmoTAbsCenter) / uAtmoTAbsWidth)
			) * dt;
		}
		od /= sunLen; // squashed → world path length
		vec3 tau = uAtmoTBetaR * od.x + uAtmoTBetaMExt * od.y + uAtmoTBetaA * od.z;
		// Only the slant excess over the texture's baked vertical column —
		// noon stays untouched, the terminator reddens.
		float h0 = max(length(p) - 1.0, 0.0);
		vec3 tauVert = uAtmoTBetaR * (uAtmoTRayleighH * exp(-h0 / uAtmoTRayleighH)) +
			uAtmoTBetaMExt * (uAtmoTMieH * exp(-h0 / uAtmoTMieH)) +
			uAtmoTBetaA * atmoTTentColumn(h0);
		return exp(-max(tau - uAtmoTBakedComp * tauVert, vec3(0.0)));
	}

	// Diffuse sky irradiance on a surface inside the column: the profile's
	// downward flux from above and ground-bounced flux from below, weighted by
	// the normal's tilt, scaled by the sun's height over the local horizontal
	// with a floor through the column's twilight band (the top stays lit until
	// the sun is ~8° under the surface horizon). Zero elsewhere, and faded by
	// the camera's own crossing of the top so the ground light never pops.
	vec3 atmoDeepSkyLight(vec3 worldPos, vec3 worldNormal) {
		if (!atmoTUnderDeck() || uAtmoTEnable < 0.5 || uAtmoTDeepBlend <= 0.0) return vec3(0.0);
		vec3 rel = (worldPos - uAtmoTCenter) / uAtmoTRadiusScene;
		float zf = (length(rel) - uAtmoTDeepBaseR) / uAtmoTDeepSpanR;
		vec3 up = normalize(rel);
		float s = dot(up, uAtmoTSunDir);
		float sun = max(s, 0.06 * smoothstep(-0.15, -0.02, s));
		// Re-exposed at any altitude like the sky (deepDownFlux): unit
		// luminance or unit brightest channel, whichever is larger.
		vec3 down = atmoTDeepTap(0.0, zf);
		float exposure = max(dot(down, vec3(0.2126, 0.7152, 0.0722)), max(down.r, max(down.g, down.b)));
		down *= (uAtmoTDeepIrradiance * sun) / max(exposure, 1e-4);
		float w = 0.5 + 0.5 * dot(worldNormal, up);
		return mix(down * atmoTDeepTap(1.0, zf), down, w) * uAtmoTDeepBlend;
	}
`;

/**
 * Chroma (T/lum(T)) of the air on the camera→`worldPos` ray. The shell over
 * the same pixel dims by its own marched transmittance's luminance, so the
 * product is true per-channel filtering; rays missing the shell stay neutral.
 * No baked offset — sky paths carry no texture. Uniforms: {@link ViewTintUniforms}.
 */
export const VIEW_TINT_GLSL = `
	${PARAM_DECLS}

	vec3 atmoViewTint(vec3 worldPos) {
		if (uAtmoTEnable < 0.5) return vec3(1.0);
		vec3 p = atmoTSquash((cameraPosition - uAtmoTCenter) / uAtmoTRadiusScene);
		vec3 rd = atmoTSquash(normalize(worldPos - cameraPosition));
		float rdLen = length(rd);
		rd /= rdLen;
		float b = dot(p, rd);
		float c = dot(p, p);
		float d = b * b - (c - uAtmoTBlockR * uAtmoTBlockR);
		if (d > 0.0 && -b - sqrt(d) > 0.0) return vec3(1.0);
		d = b * b - (c - uAtmoTTopR * uAtmoTTopR);
		if (d <= 0.0) return vec3(1.0);
		float s = sqrt(d);
		float t1 = -b + s;
		if (t1 <= 0.0) return vec3(1.0);
		float t0 = max(-b - s, 0.0);
		float dt = (t1 - t0) / ${FRAGMENT_STEPS.toFixed(1)};
		vec3 od = vec3(0.0);
		for (int i = 0; i < ${FRAGMENT_STEPS}; i++) {
			float h = max(length(p + rd * (t0 + dt * (float(i) + 0.5))) - 1.0, 0.0);
			od += vec3(
				exp(-h / uAtmoTRayleighH),
				exp(-h / uAtmoTMieH),
				max(0.0, 1.0 - abs(h - uAtmoTAbsCenter) / uAtmoTAbsWidth)
			) * dt;
		}
		od /= rdLen; // squashed → world path length
		vec3 t = exp(-(uAtmoTBetaR * od.x + uAtmoTBetaMExt * od.y + uAtmoTBetaA * od.z));
		float lum = dot(t, vec3(0.2126, 0.7152, 0.0722));
		return t / max(lum, 1e-4);
	}
`;

/** Param-driven uniforms shared by both GLSL patches — sync with
 *  {@link syncSunTransmittanceUniforms} (the debug tuner re-syncs live). */
export interface SunTransmittanceParamUniforms {
	uAtmoTBetaR: { value: Vector3 };
	uAtmoTBetaMExt: { value: Vector3 };
	uAtmoTBetaA: { value: Vector3 };
	uAtmoTRayleighH: { value: number };
	uAtmoTMieH: { value: number };
	uAtmoTAbsCenter: { value: number };
	uAtmoTAbsWidth: { value: number };
	uAtmoTTopR: { value: number };
	uAtmoTBlockR: { value: number };
	uAtmoTBakedComp: { value: number };
	uAtmoTRadiusScene: { value: number };
	uAtmoTEnable: { value: number };
	uAtmoTSpinAxis: { value: Vector3 };
	uAtmoTStretch: { value: number };
	uAtmoTMeshR: { value: number };
	uAtmoTDeepTex: { value: Texture };
	uAtmoTDeepN: { value: number };
	uAtmoTDeepBaseR: { value: number };
	uAtmoTDeepSpanR: { value: number };
	uAtmoTDeepKmPerRadius: { value: number };
	/** Per frame: the deep sky's surface irradiance luminance (sun-scale included). */
	uAtmoTDeepIrradiance: { value: number };
	/** Per frame: the camera's weight inside the column ({@link deckBlendWeight}). */
	uAtmoTDeepBlend: { value: number };
}

/** Surface-patch handle: params + the re-bound eclipse sun-dir/centre refs. */
export interface SunTransmittanceUniforms extends SunTransmittanceParamUniforms {
	uAtmoTSunDir: { value: Vector3 };
	uAtmoTCenter: { value: Vector3 };
}

/** View-tint handle: params + an owned centre, re-aimed per frame at whichever
 *  shell sits near the camera ({@link bindViewTint}). */
export interface ViewTintUniforms extends SunTransmittanceParamUniforms {
	uAtmoTCenter: { value: Vector3 };
}

function makeParamUniforms(enable: { value: number }): SunTransmittanceParamUniforms {
	return {
		uAtmoTBetaR: { value: new Vector3() },
		uAtmoTBetaMExt: { value: new Vector3() },
		uAtmoTBetaA: { value: new Vector3() },
		uAtmoTRayleighH: { value: 0 },
		uAtmoTMieH: { value: 0 },
		uAtmoTAbsCenter: { value: 0 },
		uAtmoTAbsWidth: { value: 0 },
		uAtmoTTopR: { value: 0 },
		uAtmoTBlockR: { value: 0 },
		uAtmoTBakedComp: { value: 0 },
		uAtmoTRadiusScene: { value: 0 },
		uAtmoTEnable: enable,
		uAtmoTSpinAxis: { value: new Vector3(0, 1, 0) },
		uAtmoTStretch: { value: 1 },
		uAtmoTMeshR: { value: 1 },
		uAtmoTDeepTex: { value: whiteTexture() },
		uAtmoTDeepN: { value: 1 },
		uAtmoTDeepBaseR: { value: 1 },
		uAtmoTDeepSpanR: { value: 0 },
		uAtmoTDeepKmPerRadius: { value: 1 },
		uAtmoTDeepIrradiance: { value: 0 },
		uAtmoTDeepBlend: { value: 0 }
	};
}

// Sampler placeholder while a body has no deep column — the uniform must
// still be bound.
let white: DataTexture | null = null;
function whiteTexture(): DataTexture {
	if (!white) {
		white = new DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1);
		white.needsUpdate = true;
	}
	return white;
}

/** (Re-)derive every param-driven uniform, radius-normalised like the shell
 *  (`planetRadius*` is the solid body's; the deck offset is added here). */
export function syncSunTransmittanceUniforms(
	u: SunTransmittanceParamUniforms,
	params: AtmosphereParams,
	planetRadiusScene: number,
	planetRadiusKm: number
): void {
	const surfaceKm = planetRadiusKm;
	planetRadiusKm = referenceRadiusKm(params, surfaceKm);
	planetRadiusScene = (planetRadiusScene * planetRadiusKm) / surfaceKm;
	const toNorm = (perKm: number) => perKm * planetRadiusKm;
	const r = params.rayleighScatterPerKm;
	const ms = params.mieScatterPerKm;
	const ma = params.mieAbsorptionPerKm;
	const ab = params.absorptionPerKm;
	u.uAtmoTBetaR.value.set(toNorm(r[0]), toNorm(r[1]), toNorm(r[2]));
	u.uAtmoTBetaMExt.value.set(toNorm(ms[0] + ma[0]), toNorm(ms[1] + ma[1]), toNorm(ms[2] + ma[2]));
	u.uAtmoTBetaA.value.set(toNorm(ab[0]), toNorm(ab[1]), toNorm(ab[2]));
	u.uAtmoTRayleighH.value = params.rayleighScaleHeightKm / planetRadiusKm;
	u.uAtmoTMieH.value = params.mieScaleHeightKm / planetRadiusKm;
	u.uAtmoTAbsCenter.value = params.absorptionCenterKm / planetRadiusKm;
	u.uAtmoTAbsWidth.value = params.absorptionWidthKm / planetRadiusKm;
	u.uAtmoTTopR.value = 1 + params.topAltitudeKm / planetRadiusKm;
	u.uAtmoTBlockR.value = 1 - TERRAIN_DIP_KM / planetRadiusKm - 0.015;
	u.uAtmoTBakedComp.value = params.bakedCompensation;
	u.uAtmoTRadiusScene.value = planetRadiusScene;
	const deep = params.deepColumn;
	u.uAtmoTDeepTex.value = deep ? deepColumnTexture(deep) : whiteTexture();
	u.uAtmoTDeepN.value = deep?.n ?? 1;
	u.uAtmoTDeepBaseR.value = surfaceKm / planetRadiusKm;
	u.uAtmoTDeepSpanR.value = deep ? deep.topKm / planetRadiusKm : 0;
	u.uAtmoTDeepKmPerRadius.value = planetRadiusKm;
}

/** Make a view-tint uniform set: disabled until {@link bindViewTint} aims it
 *  at a shell (own enable — proximity-driven, not the scene toggle). */
export function makeViewTintUniforms(): ViewTintUniforms {
	return { ...makeParamUniforms({ value: 0 }), uAtmoTCenter: { value: new Vector3() } };
}

/** Aim a view-tint uniform set at one body's shell for this frame. Omitted
 *  `spinAxis`/`stretch` mean a spherical body. */
export function bindViewTint(
	u: ViewTintUniforms,
	params: AtmosphereParams,
	center: Vector3,
	planetRadiusScene: number,
	planetRadiusKm: number,
	spinAxis?: Vector3,
	stretch = 1
): void {
	syncSunTransmittanceUniforms(u, params, planetRadiusScene, planetRadiusKm);
	u.uAtmoTCenter.value.copy(center);
	if (spinAxis) u.uAtmoTSpinAxis.value.copy(spinAxis);
	else u.uAtmoTSpinAxis.value.set(0, 1, 0);
	u.uAtmoTStretch.value = stretch;
	u.uAtmoTEnable.value = 1;
}

/**
 * Filter resolved direct light by the sun→fragment transmittance. Requires
 * `attachEclipseShadowToBody` first — reuses its `vEclipseWorldPos` varying.
 * Indirect light stays untouched, like the eclipse patch.
 *
 * `shell`, when given, shares the body's shell uniforms so per-frame
 * spin-axis/stretch updates propagate to the squash; omitted means identity
 * squash. `meshRadiusRatio` (host mesh radius / planet radius) snaps the
 * march start to the analytic sphere so tessellation never shows in the tint.
 */
export function attachSunTransmittanceToBody(
	material: MeshStandardMaterial,
	params: AtmosphereParams,
	planetRadiusScene: number,
	planetRadiusKm: number,
	self: EclipseSelfUniforms,
	shell?: AtmosphereNode,
	meshRadiusRatio = 1
): SunTransmittanceUniforms {
	const uniforms: SunTransmittanceUniforms = {
		...makeParamUniforms(SCENE.uAtmoTEnable),
		uAtmoTSunDir: getEclipseSceneUniforms().uSunDir,
		uAtmoTCenter: self.uEclipseSelfPos
	};
	uniforms.uAtmoTMeshR.value =
		(meshRadiusRatio * planetRadiusKm) / referenceRadiusKm(params, planetRadiusKm);
	if (shell) {
		uniforms.uAtmoTSpinAxis = shell.material.uniforms.uSpinAxis as { value: Vector3 };
		uniforms.uAtmoTStretch = shell.material.uniforms.uStretch as { value: number };
	}
	syncSunTransmittanceUniforms(uniforms, params, planetRadiusScene, planetRadiusKm);
	chainShaderHook(material, 'sunTint', (shader) => {
		Object.assign(shader.uniforms, uniforms);
		shader.fragmentShader = shader.fragmentShader
			.replace('#include <common>', `#include <common>\n${SUN_TINT_GLSL}`)
			.replace(
				'#include <lights_fragment_end>',
				`#include <lights_fragment_end>
				vec3 atmoTint = atmoSunTint(vEclipseWorldPos);
				reflectedLight.directDiffuse *= atmoTint;
				reflectedLight.directSpecular *= atmoTint;
				reflectedLight.indirectDiffuse +=
					atmoDeepSkyLight(vEclipseWorldPos, inverseTransformDirection(normal, viewMatrix)) *
					BRDF_Lambert(diffuseColor.rgb);`
			);
	});
	return uniforms;
}

/**
 * View-ray chroma for a chunk-based material (the tuner's sun disc). Custom
 * ShaderMaterials (the production photosphere) embed {@link VIEW_TINT_GLSL}
 * directly instead.
 */
export function attachViewTintToMaterial(material: Material): ViewTintUniforms {
	const uniforms = makeViewTintUniforms();
	chainShaderHook(material, 'viewTint', (shader) => {
		Object.assign(shader.uniforms, uniforms);
		shader.vertexShader = shader.vertexShader
			.replace('#include <common>', '#include <common>\nvarying vec3 vAtmoTWorldPos;')
			.replace(
				'#include <begin_vertex>',
				'#include <begin_vertex>\nvAtmoTWorldPos = (modelMatrix * vec4(position, 1.0)).xyz;'
			);
		shader.fragmentShader = shader.fragmentShader
			.replace(
				'#include <common>',
				`#include <common>\nvarying vec3 vAtmoTWorldPos;\n${VIEW_TINT_GLSL}`
			)
			.replace(
				'#include <color_fragment>',
				'#include <color_fragment>\ndiffuseColor.rgb *= atmoViewTint(vAtmoTWorldPos);'
			);
	});
	return uniforms;
}

const _p = new Vector3();
const _sd = new Vector3();

/** In-place squashed-space transform, mirroring the GLSL `atmoTSquash`. */
function squash(v: Vector3, spinAxis: Vector3 | undefined, stretch: number): Vector3 {
	if (!spinAxis || stretch === 1) return v;
	return v.addScaledVector(spinAxis, (stretch - 1) * v.dot(spinAxis));
}

/**
 * CPU twin of the fragment march, along the camera→Sun ray. `camRelPos` is
 * camera − body centre in scene units. Writes `out`; false when the ray
 * misses the shell or the body blocks the sun (disc occluded — no tint).
 * Omitted `spinAxis`/`stretch` mean a spherical body.
 */
export function sunPathTransmittance(
	params: AtmosphereParams,
	camRelPos: Vector3,
	sunDir: Vector3,
	planetRadiusScene: number,
	planetRadiusKm: number,
	out: Vector3,
	spinAxis?: Vector3,
	stretch = 1
): boolean {
	const surfaceKm = planetRadiusKm;
	planetRadiusKm = referenceRadiusKm(params, surfaceKm);
	planetRadiusScene = (planetRadiusScene * planetRadiusKm) / surfaceKm;
	const p = squash(_p.copy(camRelPos).divideScalar(planetRadiusScene), spinAxis, stretch);
	const sd = squash(_sd.copy(sunDir), spinAxis, stretch);
	const sunLen = sd.length();
	sd.divideScalar(sunLen);
	const topR = 1 + params.topAltitudeKm / planetRadiusKm;
	const blockR = 1 - TERRAIN_DIP_KM / planetRadiusKm - 0.015;
	const b = p.dot(sd);
	const c = p.lengthSq();
	let d = b * b - (c - blockR * blockR);
	if (d > 0 && -b - Math.sqrt(d) > 0) return false;
	d = b * b - (c - topR * topR);
	if (d <= 0) return false;
	const s = Math.sqrt(d);
	const tFar = -b + s;
	if (tFar <= 0) return false;
	const tNear = Math.max(-b - s, 0);
	const dt = (tFar - tNear) / CPU_STEPS;
	// Squashed step → world path length.
	const dtKm = (dt * planetRadiusKm) / sunLen;
	let odR = 0;
	let odM = 0;
	let odA = 0;
	for (let i = 0; i < CPU_STEPS; i++) {
		const t = tNear + dt * (i + 0.5);
		const hKm = Math.max(
			(Math.hypot(p.x + sd.x * t, p.y + sd.y * t, p.z + sd.z * t) - 1) * planetRadiusKm,
			0
		);
		odR += Math.exp(-hKm / params.rayleighScaleHeightKm) * dtKm;
		odM += Math.exp(-hKm / params.mieScaleHeightKm) * dtKm;
		odA +=
			Math.max(0, 1 - Math.abs(hKm - params.absorptionCenterKm) / params.absorptionWidthKm) * dtKm;
	}
	const r = params.rayleighScatterPerKm;
	const ms = params.mieScatterPerKm;
	const ma = params.mieAbsorptionPerKm;
	const ab = params.absorptionPerKm;
	out.set(
		Math.exp(-(r[0] * odR + (ms[0] + ma[0]) * odM + ab[0] * odA)),
		Math.exp(-(r[1] * odR + (ms[1] + ma[1]) * odM + ab[1] * odA)),
		Math.exp(-(r[2] * odR + (ms[2] + ma[2]) * odM + ab[2] * odA))
	);
	return true;
}
