import { solveKepler, solveKeplerHyperbolic, solveBarker } from './solvers';
import { AU_SCALE, AU_KM, EARTH_OBLIQUITY_DEG } from '$lib/math/units';
import type { PositionedBody } from '$lib/types/objects';
import { sgp4, SatRecError, type SatRec } from 'satellite.js';
import { buildSatrec } from './sgp4';
import { yieldToMain } from '$lib/yield';
import { J2000_JD } from '$lib/time/jd';

const DEG2RAD = Math.PI / 180;
const COS_EPS = Math.cos(EARTH_OBLIQUITY_DEG * DEG2RAD);
const SIN_EPS = Math.sin(EARTH_OBLIQUITY_DEG * DEG2RAD);
/** Precomputed km -> scene-unit scale. */
const KM_TO_SCENE = AU_SCALE / AU_KM;

export const KIND_SKIP = 0;
export const KIND_KEPLER = 1;
export const KIND_PARABOLIC = 2;
export const KIND_SGP4 = 3;

/**
 * SoA view of one point-cloud group, packed for a worker's tight solve loop.
 *
 * `kind[i]` selects the solver per body:
 *   0 = skip (promoted, a≈0 degenerate, etc.)
 *   1 = Keplerian: a, e, i, om, w, ma, n, epoch
 *   2 = Parabolic: e, i, om, w, epoch, q, tp
 *   3 = SGP4: satnum, bstar, ndot, nddot plus the Kepler columns; `satrec[i]`
 *       is the worker's own record, built on the first solve of that row
 *
 * Arrays are length `count`, Float64 throughout — precision for TNO epochs and
 * near-parabolic e; output positions are the only Float32.
 */
export interface OrbitColumns {
	count: number;
	kind: Uint8Array;
	/** 1 when i/om/w are in Earth-equatorial J2000 (TEME) instead of ecliptic. */
	equatorial: Uint8Array;
	a: Float64Array;
	e: Float64Array;
	i: Float64Array;
	om: Float64Array;
	w: Float64Array;
	ma: Float64Array;
	n: Float64Array;
	epoch: Float64Array;
	q: Float64Array;
	tp: Float64Array;
	/** Per-row SGP4 record cache, filled by `writePositions` on the solving
	 *  side; a row may also arrive pre-built (a placeholder body). */
	satrec: (SatRec | null)[];
	/** SGP4 inputs the Kepler columns lack: NORAD number, drag term, mean-motion derivatives. */
	satnum: Int32Array;
	bstar: Float64Array;
	ndot: Float64Array;
	nddot: Float64Array;
	/** SBDB bits per point (0 = NEO, 1 = PHA); zero on non-SBDB rows. */
	flags: Uint8Array;
	/** Days from J2000 to the body's origin (discovery for small bodies, launch
	 *  for Earth sats); NaN = always visible. `writePositions` hides points
	 *  whose origin is past the tick's jd. */
	visibleFromDays: Float32Array;
	/** Whether `writePositions` honours the tick's `requiredFlags` mask. False
	 *  for groups whose flags are meaningless (Earth sats) so a global NEO/PHA
	 *  filter doesn't erase them. */
	applyFlagFilter: boolean;
	/**
	 * Group-level validity window (JD TDB). Written once at pack time from the
	 * widest span across bodies — bodies in a pool group always come from one
	 * zone export so in practice they share a single chunk window. `writePositions`
	 * early-exits (returning 0) when the tick's jd falls outside this range,
	 * avoiding a futile SGP4 loop that would spam propagation warnings.
	 */
	validityStart: number;
	validityEnd: number;
	/** Base global pick-id for this group: row `idx` gets pick-id `pickBase + idx`,
	 *  written by `writePositions` into the compact `outIds` buffer for GPU picking.
	 *  The main thread maps `pickBase + idx` back to a body via {@link PickRegistry}. */
	pickBase: number;
}

/**
 * Write the columns every kind shares into row `outIdx`. `visibleFromDays` is
 * not one of them: the AoS pack path has no origin date to write and leans on
 * the allocator's NaN (= always visible), so its callers opt in themselves.
 */
export function writeCommonRow(
	out: OrbitColumns,
	outIdx: number,
	a: number,
	e: number,
	i: number,
	om: number,
	w: number,
	ma: number,
	n: number,
	epoch: number,
	equatorial: boolean | undefined,
	flags: number
): void {
	out.a[outIdx] = a;
	out.e[outIdx] = e;
	out.i[outIdx] = i;
	out.om[outIdx] = om;
	out.w[outIdx] = w;
	out.ma[outIdx] = ma;
	out.n[outIdx] = n;
	out.epoch[outIdx] = epoch;
	out.equatorial[outIdx] = equatorial ? 1 : 0;
	out.flags[outIdx] = flags;
}

/** Pack one body into row `idx` of `cols`. Returns false for KIND_SKIP rows
 *  (skipped / degenerate) so callers can exclude them from validity widening. */
function packRowInto(
	cols: OrbitColumns,
	idx: number,
	b: PositionedBody,
	skip?: Set<string>
): boolean {
	const d = b.data;
	if (skip?.has(d.id)) {
		cols.kind[idx] = KIND_SKIP;
		return false;
	}
	if (d.omm) {
		cols.kind[idx] = KIND_SGP4;
		cols.satnum[idx] = d.omm.noradCatId;
		cols.bstar[idx] = d.omm.bstar;
		cols.ndot[idx] = d.omm.meanMotionDot;
		cols.nddot[idx] = d.omm.meanMotionDdot;
	} else if (d.satrec) {
		cols.kind[idx] = KIND_SGP4;
		cols.satrec[idx] = d.satrec;
	} else if (d.q != null && d.tp != null && isFinite(d.q) && isFinite(d.tp)) {
		cols.kind[idx] = KIND_PARABOLIC;
		cols.q[idx] = d.q;
		cols.tp[idx] = d.tp;
	} else if (d.a !== 0 && isFinite(d.a)) {
		cols.kind[idx] = KIND_KEPLER;
	} else {
		cols.kind[idx] = KIND_SKIP;
		return false;
	}
	writeCommonRow(
		cols,
		idx,
		d.a,
		d.e,
		d.i,
		d.om,
		d.w,
		d.ma,
		d.n,
		d.epoch,
		d.equatorial,
		d.flags ?? 0
	);
	return true;
}

/**
 * Pack an AoS PositionedBody list into SoA columns for worker consumption.
 * IDs in `skip` and degenerate Keplerian entries (a=0, no q/tp) get KIND_SKIP.
 * Columns are sized and ordered to match `bodies` for index-based mapping;
 * `applyFlagFilter` opts the group into the per-tick NEO/PHA mask. Yields to
 * the event loop every ~6ms so a large zone (main belt is >1M rows) doesn't
 * stall input for its whole pack.
 */
export async function packBodiesSliced(
	bodies: PositionedBody[],
	skip?: Set<string>,
	applyFlagFilter: boolean = false
): Promise<OrbitColumns> {
	const count = bodies.length;
	const cols = allocColumns(count);
	cols.applyFlagFilter = applyFlagFilter;
	// Union of the bodies' validity windows. One pool group comes from a single
	// chunk in practice, so min/max collapses to that shared window — the
	// widening only guards a caller that mixes chunks into one group.
	let start = Infinity;
	let end = -Infinity;
	let sliceStart = performance.now();
	for (let idx = 0; idx < count; idx++) {
		if ((idx & 4095) === 4095 && performance.now() - sliceStart > 6) {
			await yieldToMain();
			sliceStart = performance.now();
		}
		if (!packRowInto(cols, idx, bodies[idx], skip)) continue;
		const d = bodies[idx].data;
		if (d.validityStart < start) start = d.validityStart;
		if (d.validityEnd > end) end = d.validityEnd;
	}
	cols.validityStart = start === Infinity ? -Infinity : start;
	cols.validityEnd = end === -Infinity ? Infinity : end;
	return cols;
}

type OrbitColumn = Uint8Array | Int32Array | Float32Array | Float64Array | (SatRec | null)[];

/**
 * Every per-row column of {@link OrbitColumns}. `allocColumns` and
 * `columnsTransferList` both walk this list, so the order of its transferable
 * entries is the worker-transfer contract.
 */
const COLUMNS: readonly {
	name: keyof OrbitColumns;
	make: (count: number) => OrbitColumn;
	/** False for a column with no buffer to hand a worker. */
	transferable?: false;
}[] = [
	{ name: 'kind', make: (c) => new Uint8Array(c) },
	{ name: 'equatorial', make: (c) => new Uint8Array(c) },
	{ name: 'a', make: (c) => new Float64Array(c) },
	{ name: 'e', make: (c) => new Float64Array(c) },
	{ name: 'i', make: (c) => new Float64Array(c) },
	{ name: 'om', make: (c) => new Float64Array(c) },
	{ name: 'w', make: (c) => new Float64Array(c) },
	{ name: 'ma', make: (c) => new Float64Array(c) },
	{ name: 'n', make: (c) => new Float64Array(c) },
	{ name: 'epoch', make: (c) => new Float64Array(c) },
	{ name: 'q', make: (c) => new Float64Array(c) },
	{ name: 'tp', make: (c) => new Float64Array(c) },
	{ name: 'flags', make: (c) => new Uint8Array(c) },
	// NaN default = always visible; rows with an origin date overwrite per row.
	{ name: 'visibleFromDays', make: (c) => new Float32Array(c).fill(NaN) },
	{ name: 'satnum', make: (c) => new Int32Array(c) },
	{ name: 'bstar', make: (c) => new Float64Array(c) },
	{ name: 'ndot', make: (c) => new Float64Array(c) },
	{ name: 'nddot', make: (c) => new Float64Array(c) },
	{ name: 'satrec', make: (c) => new Array<SatRec | null>(c).fill(null), transferable: false }
];

/** Buffers of OrbitColumns as a transferable list. Used when posting to a worker. */
export function columnsTransferList(cols: OrbitColumns): Transferable[] {
	const list: Transferable[] = [];
	for (const col of COLUMNS) {
		if (col.transferable === false) continue;
		list.push((cols[col.name] as ArrayBufferView).buffer as Transferable);
	}
	return list;
}

export function allocColumns(count: number): OrbitColumns {
	const cols: Record<string, unknown> = {
		count,
		applyFlagFilter: false,
		validityStart: -Infinity,
		validityEnd: Infinity,
		pickBase: 0
	};
	for (const col of COLUMNS) cols[col.name] = col.make(count);
	return cols as unknown as OrbitColumns;
}

/**
 * Write one point, rejecting coordinates the Float32 buffer can't hold. A row
 * can solve finite in f64 and still overflow on store — a hyperbolic orbit far
 * from perihelion reaches ~1e40 AU — and one Infinity makes the whole cloud's
 * bounding sphere NaN, which disables frustum culling for every point in it.
 */
function writeVertex(
	out: Float32Array,
	writeIdx: number,
	x: number,
	y: number,
	z: number
): boolean {
	if (!isFinite(Math.fround(x)) || !isFinite(Math.fround(y)) || !isFinite(Math.fround(z)))
		return false;
	out[writeIdx * 3] = x;
	out[writeIdx * 3 + 1] = y;
	out[writeIdx * 3 + 2] = z;
	return true;
}

/**
 * Write basis-relative Float32 positions (parent + offset − basis, AU_SCALE
 * units) for every body in `cols` into `out`, packed contiguously at the
 * *start* — skipped/non-finite bodies are dropped, not zero-filled, mirroring
 * {@link writeMinorPointCloud}. Returns the count written; callers must use
 * `setDrawRange` with it rather than the raw buffer length.
 */
export function writePositions(
	cols: OrbitColumns,
	jd: number,
	parentX: number,
	parentY: number,
	parentZ: number,
	basisX: number,
	basisY: number,
	basisZ: number,
	out: Float32Array,
	/** Compact per-survivor pick-id bytes (RGBA, little-endian `pickBase + idx`),
	 *  written in lockstep with `out` for GPU picking. Null to skip. */
	outIds: Uint8Array | null = null,
	requiredFlags: number = 0
): number {
	// Bail when jd is outside the chunk's validity window — avoids a full SGP4
	// sweep that would error every row and flood the console; 0 hides via setDrawRange.
	if (jd < cols.validityStart || jd > cols.validityEnd) return 0;
	const {
		count,
		kind,
		equatorial,
		a,
		e,
		i,
		om,
		w,
		ma,
		n,
		epoch,
		q,
		tp,
		satrec,
		flags,
		visibleFromDays
	} = cols;
	const filterActive = requiredFlags !== 0 && cols.applyFlagFilter;
	const pickBase = cols.pickBase;
	const capacity = (out.length / 3) | 0;
	// Hide bodies not yet existing at this jd (undiscovered/not launched).
	// visibleFromDays is days from J2000; NaN never gates, so those rows always render.
	const jdDays = jd - J2000_JD;
	let writeIdx = 0;

	for (let idx = 0; idx < count; idx++) {
		if (writeIdx >= capacity) break;
		const k = kind[idx];
		if (k === KIND_SKIP) continue;
		if (visibleFromDays[idx] > jdDays) continue;
		if (filterActive && (flags[idx] & requiredFlags) !== requiredFlags) continue;

		if (k === KIND_SGP4) {
			let sat = satrec[idx];
			if (!sat) {
				sat = buildSatrec({
					noradCatId: cols.satnum[idx],
					epochJd: epoch[idx],
					meanMotion: n[idx] / 360,
					eccentricity: e[idx],
					inclination: i[idx],
					raOfAscNode: om[idx],
					argOfPericenter: w[idx],
					meanAnomaly: ma[idx],
					bstar: cols.bstar[idx],
					meanMotionDot: cols.ndot[idx],
					meanMotionDdot: cols.nddot[idx],
					elementSetNo: 0,
					revAtEpoch: 0
				});
				if (!sat) {
					kind[idx] = KIND_SKIP;
					continue;
				}
				satrec[idx] = sat;
			}
			const tsince = (jd - sat.jdsatepoch) * 1440;
			const result = sgp4(sat, tsince);
			if (!result || sat.error !== SatRecError.None) continue;
			const xk = result.position.x;
			const yk = result.position.y;
			const zk = result.position.z;
			// km -> scene units, then TEME -> ecliptic rotation about X, then
			// ecliptic -> Three.js basis swap (see position.ts for reference).
			const xs = xk * KM_TO_SCENE;
			const yk_s = yk * KM_TO_SCENE;
			const zk_s = zk * KM_TO_SCENE;
			const yEcl = yk_s * COS_EPS + zk_s * SIN_EPS;
			const zEcl = -yk_s * SIN_EPS + zk_s * COS_EPS;
			const sx = xs;
			const sy = zEcl;
			const sz = -yEcl;
			if (
				!writeVertex(
					out,
					writeIdx,
					parentX + sx - basisX,
					parentY + sy - basisY,
					parentZ + sz - basisZ
				)
			)
				continue;
			if (outIds) {
				const pid = pickBase + idx;
				const o = writeIdx * 4;
				outIds[o] = pid & 255;
				outIds[o + 1] = (pid >>> 8) & 255;
				outIds[o + 2] = (pid >>> 16) & 255;
				outIds[o + 3] = (pid >>> 24) & 255;
			}
			writeIdx++;
			continue;
		}

		let xOrb: number, yOrb: number;
		const ei = e[idx];
		const ii = i[idx];
		const omi = om[idx];
		const wi = w[idx];

		if (k === KIND_PARABOLIC) {
			const result = solveBarker(q[idx], tp[idx], jd);
			if (!result) continue;
			xOrb = result.r * Math.cos(result.nu);
			yOrb = result.r * Math.sin(result.nu);
		} else {
			const ai = a[idx];
			if (!isFinite(ai) || !isFinite(ei) || !isFinite(ma[idx]) || !isFinite(n[idx])) continue;
			const dt = jd - epoch[idx];
			const M = (ma[idx] + n[idx] * dt) * DEG2RAD;

			let nu: number, r: number;
			if (ei < 1 || ai > 0) {
				const eClamped = Math.min(ei, 1 - 1e-7);
				const E = solveKepler(M, eClamped);
				const sinNu =
					(Math.sqrt(1 - eClamped * eClamped) * Math.sin(E)) / (1 - eClamped * Math.cos(E));
				const cosNu = (Math.cos(E) - eClamped) / (1 - eClamped * Math.cos(E));
				nu = Math.atan2(sinNu, cosNu);
				r = ai * (1 - eClamped * Math.cos(E));
			} else {
				const H = solveKeplerHyperbolic(M, ei);
				if (!isFinite(H)) continue;
				const denom = ei * Math.cosh(H) - 1;
				if (Math.abs(denom) < 1e-15) continue;
				const sinNu = (Math.sqrt(ei * ei - 1) * Math.sinh(H)) / denom;
				const cosNu = (ei - Math.cosh(H)) / denom;
				nu = Math.atan2(sinNu, cosNu);
				r = ai * (1 - ei * Math.cosh(H));
			}
			xOrb = r * Math.cos(nu);
			yOrb = r * Math.sin(nu);
		}

		if (!isFinite(xOrb) || !isFinite(yOrb)) continue;

		// Inline orbitalToThreeJS — avoids tuple alloc in the hot loop.
		const cosW = Math.cos(wi * DEG2RAD);
		const sinW = Math.sin(wi * DEG2RAD);
		const cosI = Math.cos(ii * DEG2RAD);
		const sinI = Math.sin(ii * DEG2RAD);
		const cosOm = Math.cos(omi * DEG2RAD);
		const sinOm = Math.sin(omi * DEG2RAD);

		const x =
			(cosOm * cosW - sinOm * sinW * cosI) * xOrb + (-cosOm * sinW - sinOm * cosW * cosI) * yOrb;
		let y =
			(sinOm * cosW + cosOm * sinW * cosI) * xOrb + (-sinOm * sinW + cosOm * cosW * cosI) * yOrb;
		let z = sinW * sinI * xOrb + cosW * sinI * yOrb;

		if (equatorial[idx]) {
			// TLE elements are in Earth-equatorial J2000 (TEME); rotate about X by ε
			// to match the ecliptic frame everything else uses.
			const yEcl = y * COS_EPS + z * SIN_EPS;
			const zEcl = -y * SIN_EPS + z * COS_EPS;
			y = yEcl;
			z = zEcl;
		}

		// Three.js mapping: ecliptic X→X, Z→Y, Y→−Z. Matches orbitalToThreeJS.
		const sx = x * AU_SCALE;
		const sy = z * AU_SCALE;
		const sz = -y * AU_SCALE;

		if (
			!writeVertex(
				out,
				writeIdx,
				parentX + sx - basisX,
				parentY + sy - basisY,
				parentZ + sz - basisZ
			)
		)
			continue;
		if (outIds) {
			const pid = pickBase + idx;
			const o = writeIdx * 4;
			outIds[o] = pid & 255;
			outIds[o + 1] = (pid >>> 8) & 255;
			outIds[o + 2] = (pid >>> 16) & 255;
			outIds[o + 3] = (pid >>> 24) & 255;
		}
		writeIdx++;
	}
	return writeIdx;
}
