const { PI, sin, cos, asin, atan2, sqrt } = Math;
const DEG = 180 / PI;
const RAD = PI / 180;

/**
 * Rotate a 3-vector by a quaternion [x, y, z, w] (or its inverse).
 * Matches three.js convention so callers can pass `mesh.quaternion.toArray()`.
 */
function applyQuat(
	v: [number, number, number],
	q: [number, number, number, number],
	inverse: boolean
): [number, number, number] {
	const [x, y, z] = v;
	const [qx, qy, qz, qw] = inverse ? [-q[0], -q[1], -q[2], q[3]] : q;
	const ix = qw * x + qy * z - qz * y;
	const iy = qw * y + qz * x - qx * z;
	const iz = qw * z + qx * y - qy * x;
	const iw = -qx * x - qy * y - qz * z;
	return [
		ix * qw + iw * -qx + iy * -qz - iz * -qy,
		iy * qw + iw * -qy + iz * -qx - ix * -qz,
		iz * qw + iw * -qz + ix * -qy - iy * -qx
	];
}

/**
 * Camera-relative-to-target → spherical degrees. With `bodyQuat`, lat/lon
 * are body-fixed (0,0 = prime meridian on equator, east positive);
 * otherwise scene-frame (Y-up).
 */
export function cartesianToSpherical(
	cam: [number, number, number],
	target: [number, number, number],
	bodyQuat?: [number, number, number, number]
): { latitude: number; longitude: number; distance: number } {
	let dx = cam[0] - target[0];
	let dy = cam[1] - target[1];
	let dz = cam[2] - target[2];
	const distance = sqrt(dx * dx + dy * dy + dz * dz);
	if (bodyQuat) {
		[dx, dy, dz] = applyQuat([dx, dy, dz], bodyQuat, true);
	}
	return {
		latitude: asin(dy / distance) * DEG,
		longitude: bodyQuat
			? atan2(-dz, dx) * DEG // body frame: +X = prime meridian, -Z = east
			: atan2(dx, dz) * DEG,
		distance
	};
}

/**
 * Spherical degrees → world-space camera position.
 * When `bodyQuat` is given, lat/lon are interpreted as body-fixed.
 */
export function sphericalToCartesian(
	target: [number, number, number],
	lat: number,
	lon: number,
	distance: number,
	bodyQuat?: [number, number, number, number]
): [number, number, number] {
	const latR = lat * RAD;
	const lonR = lon * RAD;
	let ox: number;
	let oy: number;
	let oz: number;
	if (bodyQuat) {
		const local: [number, number, number] = [
			distance * cos(latR) * cos(lonR),
			distance * sin(latR),
			-distance * cos(latR) * sin(lonR)
		];
		[ox, oy, oz] = applyQuat(local, bodyQuat, false);
	} else {
		ox = distance * cos(latR) * sin(lonR);
		oy = distance * sin(latR);
		oz = distance * cos(latR) * cos(lonR);
	}
	return [target[0] + ox, target[1] + oy, target[2] + oz];
}

/**
 * Scene-frame camera offset placing the camera on the far side of `focus`
 * from `toward`, lifted `elevationDeg` above the ecliptic (+Y) — so looking
 * at `focus` also looks toward `toward`. Falls back to +Z when coincident.
 */
export function offsetFacing(
	focus: [number, number, number],
	toward: [number, number, number],
	elevationDeg: number,
	distance: number
): [number, number, number] {
	// Anti-`toward` horizontal direction (ecliptic plane); +Y is dropped.
	let hx = focus[0] - toward[0];
	let hz = focus[2] - toward[2];
	const hl = sqrt(hx * hx + hz * hz);
	if (hl > 0) {
		hx /= hl;
		hz /= hl;
	} else {
		hx = 0;
		hz = 1;
	}
	const e = elevationDeg * RAD;
	const c = cos(e);
	return [distance * c * hx, distance * sin(e), distance * c * hz];
}

/** Longitude folded into the range the map reports, (−180°, 180°]. */
export function wrapLongitude(deg: number): number {
	const wrapped = ((deg + 180) % 360) - 180;
	return wrapped <= -180 ? wrapped + 360 : wrapped;
}

/**
 * A longitude held inside a band, which may run through the antimeridian: 170°
 * to −170° is the twenty degrees across it, not the three hundred and forty the
 * other way. Outside the band the nearer edge wins. One edge alone leaves the
 * other at the antimeridian, so `max` of 30° is the band −180° to 30°.
 */
export function clampLongitude(lon: number, min?: number, max?: number): number {
	if (min === undefined && max === undefined) return lon;
	// A western edge on the antimeridian is −180, or −180 to 180 would fold to
	// the one meridian at 180 and pin every place to it.
	const wrappedMin = min === undefined ? -180 : wrapLongitude(min);
	const west = wrappedMin === 180 ? -180 : wrappedMin;
	const east = max === undefined ? 180 : wrapLongitude(max);
	const inside = west <= east ? lon >= west && lon <= east : lon >= west || lon <= east;
	if (inside) return lon;
	const gap = (a: number, b: number) => Math.abs(wrapLongitude(a - b));
	return gap(lon, west) <= gap(lon, east) ? west : east;
}
